399		conn.setReadDeadline(2 * time.Second)
400		code := conn.readCloseCode()
401		conn.clearReadDeadline()
402		if code != 4403 {
403			t.Fatalf("close code = %d, want 4403", code)
404		}
405	
406		// A reconnect while revoked is a pre-upgrade 403; nothing arrives on the
407		// old connection after a later commit.
408		postDocChange(t, srv, "dev-1", "doc", "after-revoke", map[string]any{"x": 1})
409		conn.setReadDeadline(300 * time.Millisecond)
