416		if conn2 != nil || resp2.StatusCode != http.StatusForbidden {
417			if conn2 != nil {
418				conn2.close()
419			}
420			t.Fatalf("reconnect while revoked = %d, want 403", resp2.StatusCode)
421		}
422	
423		// Grant restores access; a fresh subscription streams again.
424		if code := postHTTP(t, srv, "/v1/documents/doc/permissions", map[string]any{
425			"deviceId": "dev-1", "action": "grant",
426		}); code != http.StatusOK {
