754	// Register commits that move the winning value push immediately; idempotent
755	// repeats, losing (lower-version) ops carrying an already-winning value, and
756	// rejected stalls change no state and push nothing.
757	func TestCRDTSubscribeRegisterPushesOnlyRealChanges(t *testing.T) {
758		srv, _ := newWSTestServer(t)
759		setupSession(t, srv, "dev-1", "sess", "doc", 0)
760	
761		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
762		if conn == nil {
763			t.Fatalf("status = %d, want 101", hs.StatusCode)
764		}
765		defer conn.close()
766	
767		// First ever state: the v1 string.
768		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a1", 1, "one"))); code != http.StatusOK {
769			t.Fatalf("submit = %d", code)
770		}
771		state := conn.readCRDTState()
772		if state.Type != "register" || string(state.Value) != `"one"` {
773			t.Fatalf("frame = %s %s, want register \"one\"", state.Type, state.Value)
774		}
775	
776		// Idempotent repeat of the same op pushes nothing.
777		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a1", 1, "one"))); code != http.StatusOK {
778			t.Fatalf("idempotent resubmit = %d", code)
779		}
780		// A stalled version is a 409 and pushes nothing.
781		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a2", 1, "stall"))); code != http.StatusConflict {
782			t.Fatalf("stall = %d, want 409", code)
783		}
784		conn.setReadDeadline(300 * time.Millisecond)
785		if _, _, _, ok := conn.readFrameMaybe(); ok {
786			t.Fatal("an idempotent/rejected commit pushed a frame")
787		}
788		conn.clearReadDeadline()
789	
790		// A greater version pushes the new winning value.
791		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-1", crdtRegisterOp("a3", 2, "two"))); code != http.StatusOK {
792			t.Fatalf("advance = %d", code)
793		}
794		state = conn.readCRDTState()
795		if string(state.Value) != `"two"` {
796			t.Fatalf("frame = %s, want \"two\"", state.Value)
797		}
798	
799		// A new op that loses the merge (lower version from another device) is
800		// accepted but pushes nothing.
801		registerDeviceViaHTTP(t, srv, "dev-2")
802		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-2", crdtRegisterOp("b1", 1, "loser"))); code != http.StatusOK {
803			t.Fatalf("losing submit = %d", code)
804		}
805		conn.setReadDeadline(300 * time.Millisecond)
806		if _, _, _, ok := conn.readFrameMaybe(); ok {
807			t.Fatal("a losing op pushed a frame")
808		}
809		conn.clearReadDeadline()
810	
811		// A version tie goes to the smaller op id and pushes the new winner.
812		if code := postCRDTOps(t, srv, "doc", crdtRegisterBody("dev-2", crdtRegisterOp("a0", 2, "tie-winner"))); code != http.StatusOK {
813			t.Fatalf("tie submit = %d", code)
814		}
815		state = conn.readCRDTState()
816		if string(state.Value) != `"tie-winner"` {
817			t.Fatalf("frame = %s, want \"tie-winner\"", state.Value)
818		}
819	}
