	crdtConn.setReadDeadline(300 * time.Millisecond)
	if _, _, _, ok := crdtConn.readFrameMaybe(); ok {
		t.Fatal("a change commit woke the crdt state subscription")
	}
	crdtConn.clearReadDeadline()
}

