	resp404, rawConn := dialProcessRawHandshake(t, "http://"+p.addr,
		"/v1/documents/doc/changes/subscribe?cursor=0&deviceId=ghost")
	rawConn.Close()
	if resp404.StatusCode != http.StatusNotFound {
